    "Definition": "The CAP theorem, also known as Brewer's theorem, states that in a distributed system, it is impossible to simultaneously guarantee Consistency, Availability, and Partition tolerance. A system can only have two out of these three properties.",
    "Properties": {
      "Consistency": "Every read receives the most recent write or an error.",
      "Availability": "Every request receives a response, without guarantee that it contains the most recent write.",
      "Partition_Tolerance": "The system continues to operate despite arbitrary message loss or failure between nodes."
    },
    "Examples": [
      {
        "System": "MongoDB (with default configuration)",
        "Prioritizes": ["Consistency", "Availability"],
        "Sacrifices": "Partition tolerance",
        "Explanation": "MongoDB can be configured to prioritize consistency and availability by ensuring all reads and writes go to the primary node. However, in the event of a network partition, it may not be able to function properly, thus sacrificing partition tolerance."
      },
      {
        "System": "Amazon DynamoDB",
        "Prioritizes": ["Availability", "Partition tolerance"],
        "Sacrifices": "Consistency",
        "Explanation": "DynamoDB allows for tunable consistency. It prioritizes availability and partition tolerance by allowing reads and writes to proceed even during a network partition. However, this may result in eventual consistency rather than strong consistency."
      },
      {
        "System": "Apache Cassandra",
        "Prioritizes": ["Availability", "Partition tolerance"],
        "Sacrifices": "Consistency",
        "Explanation": "Cassandra is designed for high availability and partition tolerance. It allows for tunable consistency levels, but by default, it sacrifices strong consistency to ensure the system remains available during network partitions."
      }
    ]
  }
}
